const d={ifox:{baipishu:"白皮书",jingyingxieyi:"经营协议",zhucezhengshu:"注册证书",xinwen:"新闻",rosxinbishangxian:"ROS新币上线",jihuibudengren:"机会不等人，首发新币限时申购中",xiangqing:"详情",zixun:"资讯",daibixinxi:"代币信息",daibi:"代币",wangluo:"网络",zonggongyingliang:"总供应量",renjiaojia:"认购价格",shangjiaojia:"上市价格",h1:"详细的代币分配和解锁计划将于官方白皮书中公布。",h2:"早期参与者将获得优先分配。",h3:"代币用途",h4:"ROS 为 Rocket Station 生态系统提供动力。",h5:"访问 Rocket Station Launchpad 项目",h6:"参与生态系统治理投票",h7:"平台奖励与激励",h8:"合作平台交易手续费折扣",t9:"ROS 是驱动 Rocket Station 生态系统的核心功能型代币。",t10:"代币分配",t11:"公开销售",t12:"生态发展",t13:"团队与顾问",t14:"市场营销与合作伙伴",t15:"流动性与交易所上市",t16:"社区奖励",t17:"ICO 分配有限，具体取决于实际情况。",d1:"开启Web3创新的未来",d2:"Rocket Station 是一个去中心化的 Web3 启动基础设施，旨在加速区块链创新并支持下一代去中心化项目。",d3:"该平台为新兴区块链项目提供启动基础设施、生态支持以及去中心化治理机制。通过 Rocket Station，开发者可以发布新协议，社区可以参与早期创新，投资者可以支持 Web3 技术的未来发展。",d4:"Rocket Station 旨在构建一个开放的生态系统，使区块链创新能够在没有中心化障碍的情况下发展。",d5:"叙事",d6:"下一代区块链创新不仅需要技术——还需要能够让新想法启动、扩展并触达全球社区的基础设施。",d7:"Rocket Station 正是为成为这一启动基础设施而创建。",d8:"正如火箭将卫星送入轨道以支持全球通信网络，Rocket Station 旨在将下一代去中心化项目送入 Web3 经济体系。",d9:"每一个通过 Rocket Station 启动的项目，都是迈向去中心化未来的一次新使命。",d10:"为什么选择 Rocket Station？",d11:"区块链生态系统正在快速扩展，但许多有潜力的项目在早期发展阶段面临重大障碍。",d12:"Rocket Station 通过提供去中心化启动基础设施，连接开发者、社区和投资者，解决这一问题。",d13:"主要优势包括",d14:"用于启动 Web3 项目的去中心化基础设施",d15:"为生态参与者提供早期参与机会",d16:"通过 ROS 代币实现社区驱动治理",d17:"支持新兴区块链创新",d18:"Rocket Station 致力于成为下一代去中心化创新的入口。",d19:"核心功能",d20:"Rocket Station 提供完整的启动基础设施，支持去中心化创新的发展。",d21:"去中心化启动基础设施",d22:"Rocket Station 使区块链项目能够在去中心化生态中启动，降低准入门槛并支持开放参与。",d23:"社区治理",d24:"通过 ROS 代币，社区成员可以参与治理决策，共同塑造 Rocket Station 生态的未来。",d25:"早期参与机会",d26:"Rocket Station 生态参与者可获得新兴 Web3 项目的早期参与机会。",d27:"质押与生态激励",d28:"ROS 持有者可以参与质押计划并获得生态奖励，以鼓励长期参与。",d29:"开发者生态支持",d30:"Rocket Station 为 Web3 开发者提供工具、资源和基础设施支持。",d31:"项目概览",d32:"Rocket Station 作为去中心化创新的启动枢纽。",d33:"通过提供启动基础设施、开发工具和去中心化治理机制，Rocket Station 使创新者能够将新技术带入全球市场。",d34:"该平台连接开发者、社区和投资者，构建统一生态以加速 Web3 的采用。",d35:"代币信息",d36:"代币名称",d37:"代币符号",d38:"网络",d39:"总供应量",d40:"认购价格",d41:"上市价格",d42:"代币用途",d43:"ROS 代币是 Rocket Station 生态系统的核心功能型代币。",d44:"通过 Rocket Station DAO 参与治理",d45:"优先参与生态代币发行",d46:"ROS 持有者的质押奖励",d47:"作为生态服务的支付代币",d48:"代币分配",d49:"代币销售结构",d50:"阶段",d51:"价格",d52:"种子轮",d53:"私募轮",d54:"公募轮",d55:"认购时间线",d56:"认购开始",d57:"认购结束",d58:"分发",d59:"预计上市",d60:"生态系统",d61:"Rocket Station 致力于构建一个连接开发者、社区和投资者的去中心化生态系统。",d62:"Rocket Station 生态将支持",d63:"Web3 项目启动基础设施",d64:"通过 ROS 代币进行社区治理",d65:"开发者工具与生态资源",d66:"早期区块链项目的融资机制",d67:"通过该生态，Rocket Station 致力于成为全球去中心化创新中心。",d68:"路线图",d69:"阶段1 — 基础建设",d70:"Rocket Station 概念开发",d71:"平台架构设计",d72:"生态框架规划",d73:"阶段2 — 启动",d74:"ROS 代币认购活动",d75:"社区扩展",d76:"战略生态合作伙伴关系",d77:"阶段3 — 生态增长",d78:"开发者引入",d79:"启动基础设施扩展",d80:"Web3 项目孵化",d81:"阶段4 — 全球扩展",d82:"生态规模扩展",d83:"去中心化治理发展",d84:"全球 Web3 社区整合",d85:"参与规则",d86:"用户必须完成账户注册和验证后方可参与认购活动。",d87:"认购将在官方规定时间内进行。",d88:"代币将在认购结束后进行分发。",d89:"上市价格将根据上市时的市场情况确定。",d90:"官方链接",d91:"官网",d92:"白皮书",d93:"风险提示",d94:"数字资产具有较高风险和价格波动性。",d95:"参与区块链项目应保持理性并进行独立研究。",d96:"本信息仅供参考，不构成任何投资建议。"}};export{d as default};
